(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.012+t*0.2)*20 + Math.cos(y*0.015-t*0.15)*15;
  const w1y = Math.cos(y*0.012-t*0.18)*20 + Math.sin(x*0.014+t*0.22)*15;
  const w2x = Math.sin((x+w1x)*0.008-t*0.1)*12 + Math.cos((y+w1y)*0.01+t*0.12)*10;
  const w2y = Math.cos((y+w1y)*0.008+t*0.11)*12 + Math.sin((x+w1x)*0.009-t*0.13)*10;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.5],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.0],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,2.0],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,2.5],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65)*40,0.14,1.3,3.0],
    [400+Math.cos(t*0.55+1)*70,220+Math.sin(t*0.75+2)*50,0.05,2.8,3.5],
    [200+Math.sin(t*0.7+2)*90,200+Math.cos(t*0.3+4)*60,0.11,1.6,4.0],
    [300+Math.cos(t*0.42)*110,50+Math.sin(t*0.58+1)*45,0.075,2.1,4.5]
  ];
  let aS=0,iS=0,harm=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+ph+1.5);
    harm+=Math.sin(d*f*1.5-t*sp*1.3+ph*2)*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,harmo=harm/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=(Math.sin(dist*0.06+ang*2-t*0.8)+Math.cos(dist*0.035-ang*5+t*1.0))*0.3;
  const cX=sx/28,cY=sy/28;
  const fx=cX-Math.floor(cX),fy=cY-Math.floor(cY);
  const cell=Math.tanh((Math.min(fx,1-fx,fy,1-fy)-0.25)*6)*0.5;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+sp1)*2.2);
  const r2=Math.tanh((harmo-act*0.5+sp2+cell*0.4)*1.8);
  const fb=Math.sin(r1*r2*Math.PI)*0.3;
  const blend=r1*0.5+r2*0.3+fb*0.2,v=blend*0.5+0.5;
  const pal=[
    [12,15,58],[25,55,95],[20,100,120],[30,155,135],
    [120,185,100],[210,195,80],[230,140,70],[210,85,65],
    [160,50,75],[100,30,80],[55,20,70],[12,15,58]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(r1*Math.PI)*0.15+Math.abs(r2)*0.1;
  const edge=Math.abs(blend)>0.65?1.1+Math.abs(blend)*0.15:0.9+Math.abs(blend)*0.2;
  const sh=harmo*0.05;
  return[
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f+sh*40)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f-sh*20)*lum*edge))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f+sh*30)*lum*edge))|0
  ];
}
